import test from 'node:test';import assert from 'node:assert/strict';
import {createFieldRumors,fieldRumorCandidates,FIELD_RUMOR_GAP} from '../field-rumors.js';
function fixture(){const scene={location:1,width:15,height:11,floor:Array.from({length:11},()=>'.'.repeat(15)),doors:[]},objects=[{type:'npc',name:'Ada',xy:[4,4]},{type:'affordance',affordanceId:'sluice',affordanceKind:'site',label:'flood-marked side sluice',xy:[6,4],solved:false},{type:'listen',label:'listening kiln',xy:[4,7]}],state={scene:1,x:3.5,y:4.5,mode:'field',fieldNotes:[]};let calls=0;const world={scene,state,objects(){calls++;return objects;},available:o=>!o.hidden,done:o=>!!o.completed};return {scene,objects,state,world,get calls(){return calls;}};}
function advance(r,w,seconds,opts={}){const events=[];for(let i=0;i<Math.ceil(seconds*20);i++){const e=r.update(w,.05,opts);if(e)events.push(e);}return events;}
test('an actual named resident gives a nonmodal observation about an actual unfinished nearby object',()=>{const f=fixture(),before=JSON.stringify([f.scene,f.state,f.objects]),r=createFieldRumors(),events=advance(r,f.world,9),cue=events.find(e=>e.type==='field-rumor');assert.ok(cue);assert.equal(cue.speaker,'Ada');assert.equal(cue.opportunityKey,'sluice');assert.match(cue.text,/flood-marked side sluice/);assert.deepEqual([cue.x,cue.y],[4.5,4.5]);assert.equal(cue.life,4);assert.equal(JSON.stringify([f.scene,f.state,f.objects]),before);});
test('blocked lifecycles and objective following clear captions and never emit another',()=>{for(const flag of ['blocked','guideActive','otherCueActive']){const f=fixture(),r=createFieldRumors();advance(r,f.world,9);assert.ok(r.active);const clear=r.update(f.world,.05,{[flag]:true});assert.equal(clear.type,'field-rumor-clear');assert.equal(r.active,null);assert.equal(advance(r,f.world,60,{[flag]:true}).length,0);}for(const mode of ['battle','dialog']){const f=fixture(),r=createFieldRumors();f.state.mode=mode;assert.equal(advance(r,f.world,60).length,0);assert.equal(f.calls,0);}});
test('captions expire after four seconds, obey a global 45-second gap and repeat no opportunity this session',()=>{const f=fixture(),r=createFieldRumors();const first=advance(r,f.world,9).find(e=>e.type==='field-rumor');assert.ok(r.active);assert.ok(advance(r,f.world,4).some(e=>e.type==='field-rumor-clear'));assert.equal(advance(r,f.world,35).filter(e=>e.type==='field-rumor').length,0);const second=advance(r,f.world,10).find(e=>e.type==='field-rumor');assert.ok(second);assert.notEqual(second.key,first.key);advance(r,f.world,FIELD_RUMOR_GAP+8);assert.equal(r.active,null);});
test('scanning is bounded to three times a second and cooldown does not poll objects',()=>{const f=fixture(),r=createFieldRumors();f.objects.length=0;advance(r,f.world,20);assert.ok(f.calls<=37,'only scans after the eight-second arrival margin');const g=fixture(),s=createFieldRumors();advance(s,g.world,13);const calls=g.calls;advance(s,g.world,30);assert.equal(g.calls,calls);});
test('solved, completed, inspected, unavailable and unreachable opportunities are excluded',()=>{const f=fixture();f.objects[1].solved=true;f.objects[2].completed=true;assert.deepEqual(fieldRumorCandidates(f.world,f.objects),[],'explicit completion also suppresses listening opportunities');f.objects[2].hidden=true;assert.deepEqual(fieldRumorCandidates(f.world,f.objects),[]);f.objects[1].solved=false;f.state.fieldNotes.push({scene:1,label:'flood-marked side sluice'});assert.deepEqual(fieldRumorCandidates(f.world,f.objects),[]);f.state.fieldNotes=[];f.scene.floor=f.scene.floor.map(row=>row.slice(0,5)+'#'+row.slice(6));assert.deepEqual(fieldRumorCandidates(f.world,f.objects),[]);});
test('a solved or removed target clears the active caption instead of following a stale object',()=>{for(const remove of [false,true]){const f=fixture(),r=createFieldRumors();advance(r,f.world,9);if(remove)f.objects.splice(1,1);else f.objects[1].solved=true;const events=advance(r,f.world,.4);assert.ok(events.some(e=>e.type==='field-rumor-clear'));assert.equal(r.active,null);}});
test('scene changes clear captions, retain once-per-session memory and impose a new arrival margin',()=>{const f=fixture(),r=createFieldRumors();const first=advance(r,f.world,9).find(e=>e.type==='field-rumor');f.scene={...f.scene,location:2};f.world.scene=f.scene;f.state.scene=2;assert.equal(r.update(f.world,.05).type,'field-rumor-clear');assert.equal(advance(r,f.world,7).length,0);advance(r,f.world,45);f.scene.location=1;f.state.scene=1;const later=advance(r,f.world,55).filter(e=>e.type==='field-rumor');assert.ok(later.every(e=>e.key!==first.key));});
test('without a genuine named person cues remain observations anchored to the object',()=>{const f=fixture();f.objects.shift();const cue=fieldRumorCandidates(f.world,f.objects)[0];assert.equal(cue.speaker,null);assert.deepEqual([cue.x,cue.y],[6.5,4.5]);assert.ok(!cue.text.includes('Ada'));assert.ok(!cue.text.includes('“'));});
